export const mockLibraryItems: LibraryItem[] = mockItemSummaries.map((item) => ({
  id: item.id,
  topicId: item.topicId || undefined,
  categoryId: item.categoryId,
  categoryName: item.categoryId,
  title: item.title,
  cleanTitle: item.cleanTitle || item.title,
  cover: item.coverUrl || undefined,
  coverImage: item.coverUrl || undefined,
  genre: item.genre || undefined,
  developer: item.developer || undefined,
  releaseYear: item.releaseYear || undefined,
  size: item.sizeStr || undefined,
  sizeBytes: item.sizeBytes || undefined,
  hasMagnet: item.hasMagnet,
  magnet: item.magnet || undefined,
  magnetLink: item.magnetLink || item.magnet || undefined,
  hasScreenshots: item.hasScreenshots,
  screenshots: item.hasScreenshots ? [`/screenshots/${item.id}_1.jpg`, `/screenshots/${item.id}_2.jpg`] : [],
  hasCover: Boolean(item.coverUrl),
  url: item.topicId ? `https://rutracker.org/forum/viewtopic.php?t=${item.topicId}` : undefined,
  seeders: item.seeds ?? undefined,
  leechers: item.leechers ?? undefined,
}))

export const mockItemDetails: Record<string, ItemDetail> = mockItemSummaries.reduce((acc, item) => {
  acc[item.id] = {
    ...item,
    publisher: item.developer,
    imageFormat: "ISO / NSP / XGD3",
    multiplayer: item.id === "game-3" ? "Yes (Co-op, Online)" : "No (Single-Player)",
    interfaceLanguage: "English, Japanese",
    voiceLanguage: "English",
    screenshots: item.hasScreenshots
      ? [
          `/screenshots/${item.id}_1.jpg`,
          `/screenshots/${item.id}_2.jpg`,
          `/screenshots/${item.id}_3.jpg`,
          `/screenshots/${item.id}_4.jpg`,
        ]
      : [],
    fileList: [
      { path: `${item.cleanTitle || item.title}.iso`, size: item.sizeBytes || 1048576, fileIndex: 0 },
      { path: "game_info.nfo", size: 4096, fileIndex: 1 },
    ],
    source: {
      description: `Description and details for ${item.title}.\nIncludes full single player campaign and bonuses.`,
    },
  }
  return acc
}, {} as Record<string, ItemDetail>)
